coachView.changeJsFunction:
// RiskFactor - Change Event Handler
// Executed when the widget data changes
var _this = this;

// Get the updated risk score
var riskScore = _this.getData();

console.log('RiskFactor score changed:', riskScore);

// Get configuration options
var lowThreshold = _this.getOption("lowThreshold") || 30;
var highThreshold = _this.getOption("highThreshold") || 70;
var showLabel = _this.getOption("showLabel");
if (showLabel === null || showLabel === undefined) {
    showLabel = true;
}
var showScore = _this.getOption("showScore");
if (showScore === null || showScore === undefined) {
    showScore = true;
}
var iconSize = _this.getOption("iconSize") || "medium";

// Get DOM container
var container = _this.context.element.querySelector("#riskFactorContainer");

if (!container) return;

container.innerHTML = "";

// Validate risk score
if (riskScore === null || riskScore === undefined || isNaN(riskScore)) {
    container.innerHTML = '<div class="risk-display"><span style="color: #525252;">No risk score available</span></div>';
    return;
}

// Ensure score is within 0-100 range
riskScore = Math.max(0, Math.min(100, riskScore));

// Determine risk level
var riskLevel, riskLabelText, riskIcon;

if (riskScore <= lowThreshold) {
    riskLevel = "low";
    riskLabelText = "Low Risk";
    riskIcon = '<svg viewBox="0 0 32 32"><defs><linearGradient id="lowGrad" x1="0%" y1="0%" x2="0%" y2="100%"><stop offset="0%" style="stop-color:currentColor;stop-opacity:0.3"/><stop offset="100%" style="stop-color:currentColor;stop-opacity:0.1"/></linearGradient></defs><path d="M16 3 L26 7 L26 14 C26 20 22 25 16 29 C10 25 6 20 6 14 L6 7 Z" fill="url(#lowGrad)" stroke="currentColor" stroke-width="1.5"/><path d="M12 16 L15 19 L21 12" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
} else if (riskScore < highThreshold) {
    riskLevel = "normal";
    riskLabelText = "Normal Risk";
    riskIcon = '<svg viewBox="0 0 32 32"><defs><linearGradient id="normalGrad" x1="0%" y1="0%" x2="0%" y2="100%"><stop offset="0%" style="stop-color:currentColor;stop-opacity:0.3"/><stop offset="100%" style="stop-color:currentColor;stop-opacity:0.1"/></linearGradient></defs><circle cx="16" cy="16" r="13" fill="url(#normalGrad)" stroke="currentColor" stroke-width="2"/><circle cx="16" cy="10" r="1.5" fill="currentColor"/><path d="M16 14 L16 23" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg>';
} else if (riskScore < 90) {
    riskLevel = "high";
    riskLabelText = "High Risk";
    riskIcon = '<svg viewBox="0 0 32 32"><defs><linearGradient id="highGrad" x1="0%" y1="0%" x2="0%" y2="100%"><stop offset="0%" style="stop-color:currentColor;stop-opacity:0.4"/><stop offset="100%" style="stop-color:currentColor;stop-opacity:0.2"/></linearGradient></defs><path d="M16 4 L28 26 L4 26 Z" fill="url(#highGrad)" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/><path d="M16 12 L16 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><circle cx="16" cy="22" r="1.5" fill="currentColor"/></svg>';
} else {
    riskLevel = "critical";
    riskLabelText = "Critical Risk";
    riskIcon = '<svg viewBox="0 0 32 32"><defs><linearGradient id="criticalGrad" x1="0%" y1="0%" x2="0%" y2="100%"><stop offset="0%" style="stop-color:currentColor;stop-opacity:0.5"/><stop offset="100%" style="stop-color:currentColor;stop-opacity:0.3"/></linearGradient></defs><path d="M10 4 L22 4 L28 10 L28 22 L22 28 L10 28 L4 22 L4 10 Z" fill="url(#criticalGrad)" stroke="currentColor" stroke-width="2"/><path d="M11 11 L21 21 M21 11 L11 21" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg>';
}

// Create risk display
var displayDiv = document.createElement("div");
displayDiv.className = "risk-display " + riskLevel;

// Add icon
var iconDiv = document.createElement("div");
iconDiv.className = "risk-icon " + iconSize;
iconDiv.innerHTML = riskIcon;
displayDiv.appendChild(iconDiv);

// Add info
var infoDiv = document.createElement("div");
infoDiv.className = "risk-info";

if (showLabel) {
    var labelSpan = document.createElement("span");
    labelSpan.className = "risk-label";
    labelSpan.textContent = riskLabelText;
    infoDiv.appendChild(labelSpan);
}

if (showScore) {
    var scoreSpan = document.createElement("span");
    scoreSpan.className = "risk-score";
    scoreSpan.textContent = "Score: " + riskScore + " / 100";
    infoDiv.appendChild(scoreSpan);
}

displayDiv.appendChild(infoDiv);
container.appendChild(displayDiv);

// Made with Bob

inlineScript.scriptBlock:
// RiskFactor Widget - BAW Implementation

// Get the risk score from BAW binding
var riskScore = this.getData();

// Get configuration options
var lowThreshold = this.getOption("lowThreshold");
if (lowThreshold === null || lowThreshold === undefined) {
    lowThreshold = 30;
}

var highThreshold = this.getOption("highThreshold");
if (highThreshold === null || highThreshold === undefined) {
    highThreshold = 70;
}

var showLabel = this.getOption("showLabel");
if (showLabel === null || showLabel === undefined) {
    showLabel = true;
}

var showScore = this.getOption("showScore");
if (showScore === null || showScore === undefined) {
    showScore = true;
}

var iconSize = this.getOption("iconSize");
if (!iconSize) {
    iconSize = "medium";
}

// Get DOM container
var container = this.context.element.querySelector("#riskFactorContainer");

// Function to get risk level icons with improved designs
function getLowRiskIcon() {
    // Shield with checkmark - represents protection and safety
    return '<svg viewBox="0 0 32 32"><defs><linearGradient id="lowGrad" x1="0%" y1="0%" x2="0%" y2="100%"><stop offset="0%" style="stop-color:currentColor;stop-opacity:0.3"/><stop offset="100%" style="stop-color:currentColor;stop-opacity:0.1"/></linearGradient></defs><path d="M16 3 L26 7 L26 14 C26 20 22 25 16 29 C10 25 6 20 6 14 L6 7 Z" fill="url(#lowGrad)" stroke="currentColor" stroke-width="1.5"/><path d="M12 16 L15 19 L21 12" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
}

function getNormalRiskIcon() {
    // Info circle with "i" - represents informational/moderate status
    return '<svg viewBox="0 0 32 32"><defs><linearGradient id="normalGrad" x1="0%" y1="0%" x2="0%" y2="100%"><stop offset="0%" style="stop-color:currentColor;stop-opacity:0.3"/><stop offset="100%" style="stop-color:currentColor;stop-opacity:0.1"/></linearGradient></defs><circle cx="16" cy="16" r="13" fill="url(#normalGrad)" stroke="currentColor" stroke-width="2"/><circle cx="16" cy="10" r="1.5" fill="currentColor"/><path d="M16 14 L16 23" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg>';
}

function getHighRiskIcon() {
    // Warning triangle with exclamation - represents caution
    return '<svg viewBox="0 0 32 32"><defs><linearGradient id="highGrad" x1="0%" y1="0%" x2="0%" y2="100%"><stop offset="0%" style="stop-color:currentColor;stop-opacity:0.4"/><stop offset="100%" style="stop-color:currentColor;stop-opacity:0.2"/></linearGradient></defs><path d="M16 4 L28 26 L4 26 Z" fill="url(#highGrad)" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/><path d="M16 12 L16 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><circle cx="16" cy="22" r="1.5" fill="currentColor"/></svg>';
}

function getCriticalRiskIcon() {
    // Octagon with X - represents stop/danger
    return '<svg viewBox="0 0 32 32"><defs><linearGradient id="criticalGrad" x1="0%" y1="0%" x2="0%" y2="100%"><stop offset="0%" style="stop-color:currentColor;stop-opacity:0.5"/><stop offset="100%" style="stop-color:currentColor;stop-opacity:0.3"/></linearGradient></defs><path d="M10 4 L22 4 L28 10 L28 22 L22 28 L10 28 L4 22 L4 10 Z" fill="url(#criticalGrad)" stroke="currentColor" stroke-width="2"/><path d="M11 11 L21 21 M21 11 L11 21" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg>';
}

// Function to update the risk display
function updateRiskDisplay(score, lowThresh, highThresh, showLbl, showScr, size) {
    if (!container) return;

    container.innerHTML = "";

    // Validate risk score
    if (score === null || score === undefined || isNaN(score)) {
        container.innerHTML = '<div class="risk-display"><span style="color: #525252;">No risk score available</span></div>';
        return;
    }

    // Ensure score is within 0-100 range
    score = Math.max(0, Math.min(100, score));

    // Determine risk level
    var riskLevel, riskLabelText, riskIcon;

    if (score <= lowThresh) {
        riskLevel = "low";
        riskLabelText = "Low Risk";
        riskIcon = getLowRiskIcon();
    } else if (score < highThresh) {
        riskLevel = "normal";
        riskLabelText = "Normal Risk";
        riskIcon = getNormalRiskIcon();
    } else if (score < 90) {
        riskLevel = "high";
        riskLabelText = "High Risk";
        riskIcon = getHighRiskIcon();
    } else {
        riskLevel = "critical";
        riskLabelText = "Critical Risk";
        riskIcon = getCriticalRiskIcon();
    }

    // Create risk display
    var displayDiv = document.createElement("div");
    displayDiv.className = "risk-display " + riskLevel;

    // Add icon
    var iconDiv = document.createElement("div");
    iconDiv.className = "risk-icon " + size;
    iconDiv.innerHTML = riskIcon;
    displayDiv.appendChild(iconDiv);

    // Add info
    var infoDiv = document.createElement("div");
    infoDiv.className = "risk-info";

    if (showLbl) {
        var labelSpan = document.createElement("span");
        labelSpan.className = "risk-label";
        labelSpan.textContent = riskLabelText;
        infoDiv.appendChild(labelSpan);
    }

    if (showScr) {
        var scoreSpan = document.createElement("span");
        scoreSpan.className = "risk-score";
        scoreSpan.textContent = "Score: " + score + " / 100";
        infoDiv.appendChild(scoreSpan);
    }

    displayDiv.appendChild(infoDiv);
    container.appendChild(displayDiv);
}

// Initial render
updateRiskDisplay(riskScore, lowThreshold, highThreshold, showLabel, showScore, iconSize);

// Store reference to widget instance
var me = this;

// Listen for data changes (BAW automatic updates)
if (this.context && this.context.binding) {
    var binding = this.context.binding;

    // Watch for changes to the bound data
    if (binding.addDataChangeListener) {
        binding.addDataChangeListener(function(newValue) {
            var newScore = 0;

            if (typeof newValue === "number") {
                newScore = newValue;
            }

            newScore = Math.max(0, Math.min(100, newScore));
            updateRiskDisplay(newScore, lowThreshold, highThreshold, showLabel, showScore, iconSize);
        });
    }
}

// Made with Bob

/* RiskFactor Widget - Carbon Design System */
/* Colors and typography aligned with themes/Carbon.less */

.riskfactor-container {
  width: 100%;
  font-family: 'IBM Plex Sans', 'Helvetica Neue', Helvetica, Arial, sans-serif; /* @bpm-font-family-sans-serif */
}

.risk-display {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border-radius: 4px;
  background: #ffffff; /* @bpm-body-bg */
  border: 1px solid #e0e0e0; /* Gray 20 */
  transition: all 0.2s ease;
}

.risk-display:hover {
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1);
}

/* Icon container */
.risk-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.risk-icon svg {
  display: block;
}

/* Icon sizes */
.risk-icon.small svg {
  width: 24px;
  height: 24px;
}

.risk-icon.medium svg {
  width: 32px;
  height: 32px;
}

.risk-icon.large svg {
  width: 48px;
  height: 48px;
}

/* Risk info */
.risk-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.risk-label {
  font-size: 14px; /* @bpm-font-size-base */
  font-weight: 600; /* @bpm-font-weight-semibold */
  color: #161616; /* @bpm-text-color */
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.risk-score {
  font-size: 12px; /* @bpm-font-size-small */
  font-weight: 400; /* @bpm-font-weight-normal */
  color: #525252; /* Gray 70 */
}

/* Low Risk - Green */
.risk-display.low {
  background: #d4edda;
  border-color: #198038; /* @bpm-color-success */
}

.risk-display.low .risk-icon svg {
  fill: #198038; /* @bpm-color-success */
}

.risk-display.low .risk-label {
  color: #198038; /* @bpm-color-success */
}

/* Normal Risk - Blue */
.risk-display.normal {
  background: #d0e2ff;
  border-color: #0043ce; /* @bpm-link-text-color-hover */
}

.risk-display.normal .risk-icon svg {
  fill: #0043ce; /* @bpm-link-text-color-hover */
}

.risk-display.normal .risk-label {
  color: #0043ce; /* @bpm-link-text-color-hover */
}

/* High Risk - Red */
.risk-display.high {
  background: #ffd7d9;
  border-color: #da1e28; /* @bpm-color-alert */
}

.risk-display.high .risk-icon svg {
  fill: #da1e28; /* @bpm-color-alert */
}

.risk-display.high .risk-label {
  color: #da1e28; /* @bpm-color-alert */
}

/* Critical Risk - Dark Red */
.risk-display.critical {
  background: #ffb3b8;
  border-color: #a2191f;
}

.risk-display.critical .risk-icon svg {
  fill: #a2191f;
}

.risk-display.critical .risk-label {
  color: #a2191f;
}

/* Pulse animation for high/critical risk */
.risk-display.high .risk-icon svg,
.risk-display.critical .risk-icon svg {
  animation: pulse 2s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.6;
  }
}

/* Made with Bob */
